Lemma testbit_high_small' : forall x k n, 0 <= x < 2^k -> 0 <= k <= n -> Z.testbit x n = false.
Proof.
  intros x k n Hx Hk. replace x with (x mod 2^k) by (apply Z.mod_small; lia).
  rewrite Z.testbit_mod_pow2 by lia. replace (n <? k) with false by (symmetry; apply Z.ltb_ge; lia). reflexivity.
Qed.
Lemma land_lo_hi' : forall a b k, 0 <= a < 2^k -> 0 <= k -> Z.land a (b * 2^k) = 0.
Proof.
  intros a b k Ha Hk. apply Z.bits_inj_0. intros n. rewrite Z.land_spec.
  destruct (Z.lt_ge_cases n 0) as [Hn|Hn]. { rewrite Z.testbit_neg_r by lia. reflexivity. }
  destruct (Z.lt_ge_cases n k) as [Lk|Gk].
  - rewrite Z.mul_pow2_bits by lia. rewrite (Z.testbit_neg_r b) by lia. apply Bool.andb_false_r.
  - rewrite (testbit_high_small' a k n) by lia. reflexivity.
Qed.
(* [comment removed for export] *)
Lemma lor_hi_lo' : forall a b k, 0 <= a < 2^k -> 0 <= b -> 0 <= k -> Z.lor (b * 2^k) a = a + b * 2^k.
Proof.
  intros a b k Ha Hb Hk. rewrite Z.lor_comm. pose proof (Z.add_lor_land a (b * 2^k)) as E. rewrite land_lo_hi' in E by lia. lia.
Qed.

Lemma land_M64 : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). apply Z.land_ones. lia. Qed.

(* [comment removed for export] *)
Lemma hw_code : forall x0 x1, 0 <= x0 < 256 -> 0 <= x1 < 256 ->
  Z.lor (Z.land (Z.shiftl x1 8) 18446744073709551615) x0 = x0 + x1 * 256.
Proof.
  intros x0 x1 H0 H1. rewrite land_M64, Z.shiftl_mul_pow2, Z.mod_small by lia.
  replace (x0 + x1 * 256) with (x0 + x1 * 2^8) by lia. apply lor_hi_lo'; lia.
Qed.

Lemma zb_signed8 : forall b : byte, bv_signed b = (if zb b <? 128 then zb b else zb b - 256).
Proof.
  intros b. pose proof (zb_range b) as Hr. unfold zb in *.
  unfold bv_signed, bv_swrap, bv_wrap, bv_half_modulus, bv_modulus.
  change (2 ^ Z.of_N 8)%Z with 256%Z in *. change (256 / 2)%Z with 128%Z.
  destruct (Z.ltb_spec0 (bv_unsigned b) 128).
  - rewrite Z.mod_small by lia. lia.
  - rewrite <- (Z.mod_add _ (-1)) by lia. rewrite Z.mod_small by lia. lia.
Qed.
