(* [comment removed for export] *)
Lemma verb_fail : forall rax a0x a1x a2x s0x ra sp gp tp t0 t1 t2 s1 a3 a4 a5 a6 a7 s0v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P : Z) (bs : list byte) (p' n' lo : Z),
  verb_ctx m m1 sp s0v ra P bs p' n' lo -> verb_pure sp P bs lo ->
  verb_of (zbytes bs) = 0 ->
  evt usegs (string_to_verb_post ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 s0x s1 a0x a1x a2x a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x34cf8) fc None m1 (seg_rom usegs)).
Proof.
  intros until lo. intros CTX PURE HV.
  (* [comment removed for export] *)
  step. eapply (verb_exit 0); [exact CTX | exact PURE | symmetry; exact HV].
Qed.

